"""Curated published L13 reference. Complete quoted source context travels with every rule.
No personal determination, recommendation, enrollment or production calculator is enabled.
"""
C406='cfr-406-20261027:CFR:'; C407='cfr-407-20261027:CFR:'
C408='cfr-408-20261027:CFR:'; C411='cfr-411-20261027:CFR:'
C422='cfr-422-B-20261027:CFR:'; C423='cfr-423-B-20261027:CFR:'
G='cms-2026-enrollment:GUIDE:'; L='cms-d-lep-2026:GUIDE:'
def H(s):return s+':ALL'
def R(i,title,meaning,inputs,ids):
    return dict(id=i,title=title,meaning=meaning,required_case_evidence=inputs.split('|'),source_clause_ids=ids,
                applicability='Published 2026 reference; historical and future branches retained in source context',
                personal_determination_enabled=False,qualified_R18_review=None,acceptance=None)
RULES=[
R('AB01','Eligibility and automatic enrollment',
  'Premium-free A, premium A and B have different eligibility tests. Age, disability, ALS and ESRD are distinct bases. Automatic A/B enrollment generally follows receipt of Social Security/RRB benefits sufficiently early; Puerto Rico has a B opt-in exception. Do not infer enrollment from birthday or benefit eligibility alone.',
  'SSA/RRB entitlement and award dates|residence and citizenship evidence|existing A/B effective dates|disability/ALS/ESRD basis',
  [H('cms-ab-enrollment'),C406+'406.10',C406+'406.12',C406+'406.13',C406+'406.20',C407+'407.10',C407+'407.17']),
R('AB02','Ordinary initial enrollment period',
  'The ordinary B/premium-A IEP surrounds the first eligibility month: three months before through three months after, seven months total. A first-day birthday ordinarily attains age in the preceding month. A subsequent age-65 IEP and deemed/extended IEP exceptions remain distinct. The synthetic age case assumes all non-age eligibility requirements.',
  'birth date|first eligibility month confirmed by SSA|previous disability/ESRD entitlement|deemed IEP knowledge and filing evidence',
  [C407+'407.14',C406+'406.21',H('ssa-0600805015'),H('ssa-0600805153')]),
R('AB03','IEP coverage start in 2026',
  'For eligibility on or after January 1, 2023, enrollment in the first three IEP months starts B/premium A in the first eligibility month. Enrollment in the last four starts next month. Older two/three-month delays are historical. The CMS overview next-month sentence is overbroad; the regulation and SSA control this reference.',
  'valid IEP and receipt month|first eligibility month',
  [C407+'407.25',C406+'406.22',H('ssa-0600805165'),H('cms-ab-enrollment')]),
R('AB04','General enrollment period',
  'GEP ordinarily runs January 1 through March 31 (2026 ends on a Tuesday). SSA non-workday-end extensions and deemed-filing rules are retained. For 2026 enrollment coverage starts the first of the following month, not July 1. An overlapping available SEP can have different consequences; retain choice and evidence rather than assuming a penalty.',
  'enrollment receipt|available IEP/SEP|coverage and premium history',
  [C407+'407.15',C407+'407.25',C406+'406.21',H('ssa-0600805025'),H('ssa-0600805275')]),
R('AB05','Premium-free A retroactivity and HSA',
  'Premium-free A may be requested after first eligibility and can be retroactive up to six months, never before eligibility. This is not a general six-month B rule. Medicare-covered months, including retroactive months, prevent HSA contributions for those months; the IRS publication is a 2025 edition used for that structural rule, not 2026 HSA limits.',
  'SSA award and application|first eligibility month|premium-free A entitlement|HSA contribution/tax records',
  [C406+'406.6',C406+'406.10',H('cms-ab-enrollment'),H('irs-hsa-969')]),
R('AB06','Disability, ALS, ESRD and limited B-ID',
  'Ordinary disability entitlement generally begins with the 25th disability-benefit month; ALS removes that waiting period. ESRD is application- and treatment-dependent, ordinarily dialysis month four with home-training/transplant exceptions and later termination rules. Immunosuppressive-drug-only Part B-ID is limited coverage and does not by itself establish full B or MA eligibility.',
  'SSA/RRB award basis and benefit months|dialysis/training/transplant records|other insurance|A/B-ID award',
  [C406+'406.12',C406+'406.13',C407+'407.55',C407+'407.57',H('cms-ab-enrollment')]),
R('AB07','Current-employment SEP eligibility',
  'The ordinary employment SEP needs qualifying current-employment GHP/LGHP coverage and the required continuous history. Age-65 coverage may be through self/spouse; disability can also use family-member LGHP under its conditions. ESRD alone does not qualify. COBRA/retiree insurance is not current-employment coverage. Employee-count payer thresholds must not become an invented universal SEP threshold.',
  'CMS-L564 or alternative employer evidence|current-employment and coverage dates|relationship|entitlement basis|coverage continuity',
  [C406+'406.24',C407+'407.20',H('ssa-0600805265'),H('ssa-0600805266'),H('ssa-0600805295')]),
R('AB08','Current-employment SEP deadline and coverage choice',
  'The SEP includes covered months and ends on the last day of the eighth consecutive month with no qualifying current-employment coverage; a partial covered month counts as covered. Enrollment while covered or in the first full uncovered month allows the enrollment month or one of the next three; later SEP months start next month. Restored coverage, retroactive termination notices, deaths and IEP overlap require the detailed SSA branches. Use 406.24(e), despite stale B cross-references to (d).',
  'last qualifying covered month|employment end|termination notice date|any restored coverage|enrollment receipt and desired effective date|IEP overlap',
  [C406+'406.24',C407+'407.20',C407+'407.25',H('ssa-0600805275'),H('ssa-0600805276'),H('ssa-0600805277')]),
R('AB09','International volunteer SEP',
  'A qualifying tax-exempt sponsored program must cover at least 12 months; the person need not serve all 12. Required health insurance and first-eligibility/previous-enrollment continuity apply. The six-month SEP begins the first day of the month a qualifying condition ceases; coverage begins next month after enrollment. Working-disabled premium-A exception and surcharge rollback conditions are retained. Do not use the CMS overview next-month start or infer blanket forgiveness of earlier nonqualifying gaps.',
  'sponsor tax status|program duration|foreign health insurance|service and termination dates|prior Medicare coverage|surcharge history',
  [C406+'406.25',C407+'407.21',H('ssa-0600805350'),H('ssa-0600805355'),H('ssa-0601001010'),H('cms-ab-enrollment')]),
R('AB10','A/B emergency or disaster SEP',
  'A qualifying federal/state/local declaration and a missed enrollment opportunity caused by the event are required. Residence can be the person or specified decision-maker. Window begins the earlier declared/incident start and ends six months after the applicable declaration end/extensions/revocation. This is not the C/D two-full-calendar-month disaster window. No active Collier declaration is inferred.',
  'declaration and amendments/end|residence or representative relationship|missed enrollment window and causal evidence',
  [C406+'406.27',C407+'407.23',H('ssa-0600805382')]),
R('AB11','A/B employer or plan misrepresentation SEP',
  'Document or attest to material misinformation that caused a missed enrollment opportunity. The SEP starts on notifying SSA and ends six months later; coverage generally starts next month. Eligibility is not established just by reporting dissatisfaction.',
  'misinformation and authorized source|missed period|notification and SSA decision',
  [C406+'406.27',C407+'407.23']),
R('AB12','A/B release from incarceration SEP',
  'For 2026 releases use the post-2025 confinement definition, including the halfway-house distinction. The SEP runs from release to the last day of the 12th month after release month. Prospective next-month coverage or an elected retroactive option of up to six months has release-month and premium-payment constraints; do not shift all releases to an ordinary anniversary date.',
  'SSA release record|confinement/halfway-house status|missed coverage|application and retroactive election|premiums',
  [C406+'406.27',C407+'407.23']),
R('AB13','A/B Medicaid termination SEP',
  'Qualifying Medicaid eligibility termination and missed Medicare enrollment are needed. Window starts at notification and ends six months after termination. Prospective next-month or elected retroactive coverage requires the source conditions/premiums. Still having Medicaid/MSP without an impending termination does not establish this SEP; L12 state eligibility findings are not supplied by L13.',
  'agency notice and actual termination date|Medicare eligibility|missed enrollment|retroactive election and premiums',
  [C406+'406.27',C407+'407.23',H('cms-ab-enrollment')]),
R('AB14','Other exceptional conditions and equitable relief',
  'Other A/B exceptional conditions require an agency determination and an event outside the individual’s control, not automatic relief for forgetfulness. The agency sets a period of at least six months. Equitable relief for federal error is a distinct route. Do not calculate a personal deadline without the decision/notice.',
  'event and prevention evidence|SSA/CMS finding and notice|federal-error evidence where relevant',
  [C406+'406.27',C407+'407.23',C406+'406.38',C407+'407.32',H('cms-ab-enrollment')]),
R('AB15','Certain TRICARE enrollment relief',
  'CMS describes a narrow under-65 disability/ESRD TRICARE B SEP with notification-dependent enrollment and effective dates. Retired/TFL and active-duty paths differ. This is not a blanket military or VA exemption from Part B enrollment or penalties; exact award/notice facts and SSA/TRICARE confirmation are needed.',
  'TRICARE status|under-65 basis|A entitlement notice|B refusal/termination and receipt|agency confirmation',
  [H('cms-ab-enrollment'),H('tricare-medicare-eligibility')]),
R('CD01','MA and Part D prerequisites',
  'MA ordinarily requires A entitlement and B enrollment, service-area residence and applicable citizenship/lawful-presence conditions; PDP needs A or B plus its residence conditions. SNP/MSA/Cost/employer/PACE restrictions are separate. The 2027 transition memo is future context, not authority to apply a future noncitizen rule to the 2026 catalog.',
  'A/B award|residence|lawful-presence status where applicable|plan/type/SNP prerequisites',
  [C422+'422.50',C423+'423.30',G+'20',G+'20.2',G+'20.3',G+'20.4',G+'20.8.3',G+'20.8.4',H('cms-2027-transition-memo')]),
R('CD02','PDP compatibility and no-loss safeguards',
  'A standalone PDP generally cannot accompany an MA HMO/PPO; PFFS without drug coverage, MSA and certain Cost arrangements have explicit exceptions. A PDP enrollment can cause MA disenrollment. Employer/retiree family coverage may be lost; verify sponsor terms before any switch. A Medicare SEP does not by itself establish Medigap buying rights in L11.',
  'existing coverage type and drug integration|employer/retiree terms|desired transaction|L11 rights evidence',
  [G+'20.1',G+'50.7',C423+'423.30',H('medicare-retiree-coordination'),H('medicare-pace-rules')]),
R('CD03','Part D IEP and retroactive entitlement',
  'Ordinary D IEP follows the B IEP, with a separate seven-month window if D-eligible only later. Retroactive Medicare notice can create a notice-month-plus-three-month opportunity. Earliest coverage must respect actual A-or-B and D eligibility, not only the application date. Keep subsequent age-65 IEP/reset separate.',
  'D first eligibility|A/B dates|B IEP|retroactive notice date|prior D/LIS history',
  [C423+'423.38',C423+'423.40',G+'30.1',G+'30.6.2',L+'30.1.1',L+'30.1.3']),
R('CD04','MA initial coverage election period',
  'ICEP begins three months before first entitlement to both A and B; ends at the later of the last day of the second month after that month or the end of B IEP. The operative January/current regulation and 2026 guide main rule agree. The guide’s old three-month note and delayed-B examples conflict and are not used for synthetic date expectations.',
  'first month of both A and B|B IEP end|election receipt|no disqualifying enrollment',
  [C422+'422.62','ecfr-422-62-jan:CFR:422.62',C422+'422.68',G+'30.2']),
R('CD05','Annual election period and correct coverage year',
  'AEP is October 15 through December 7 for coverage January 1 of the following year. Thus 2026 coverage-year AEP occurred in 2025; fall 2026 ordinarily selects 2027. AEP dates do not authorize relabeling the 2026 plan inventory or 2026 penalty constant as 2027.',
  'election receipt|selected coverage year|actual plan-year inventory',
  [C422+'422.62',C422+'422.68',C423+'423.38',C423+'423.40',G+'30.3']),
R('CD06','MA open enrollment period',
  'January 1–March 31 MA OEP permits one election by a person already enrolled in MA, to another MA plan or Original Medicare with a coordinating PDP election. It is not a general Original-Medicare-to-MA or standalone-PDP switch period. Newly eligible people enrolled in MA also have the specified first-three-month opportunity. MSA restrictions and actual receipt/effective dates remain.',
  'current MA enrollment|prior OEP election|first A+B months if newly eligible|desired transaction',
  [C422+'422.62',C422+'422.68',C423+'423.38',C423+'423.40',G+'30.4']),
R('CD07','Institutional windows',
  'MA OEPI permits eligible institutionalized individuals to make elections while institutionalized and through the last day of the second month after leaving. Part D institutional and OEPI-coordination SEPs are separate source branches. Institution definition, actual dates and Part D eligibility remain necessary; ordinary housing is not automatically institutional status.',
  'qualifying institution|entry/residence/discharge dates|current plan and intended election',
  [C422+'422.62',C423+'423.38','cfr-422-2-20261027:CFR:422.2',G+'30.5',G+'30.6.5',G+'30.6.6']),
R('CD08','Complete published MA/PDP SEP inventory',
  'Retain all 27 numbered MA and 36 Part D regulatory SEP roots, including nested conditions, approval/notice requirements and historical branches; MA b9 expired in 2020. Reconcile all 36 CMS guidance SEP sections to those roots or their non-SEP regulatory context. This is finite source accounting, not a claim that every root is an active Collier right or an accepted executable personal rule.',
  'route-specific evidence listed in source-native SEP records|actual dated plan/CMS/agency notices|permitted transaction',
  [C422+'422.62',C423+'423.38',G+'30.6']),
R('CD09','Dual/LIS monthly and integrated-care elections',
  'Eligible LIS individuals have a one-time-per-month PDP election, subject to the at-risk drug-management exception. This is not unrestricted monthly MA switching. The integrated-care monthly route requires full-benefit dual status and aligned Medicaid managed-care enrollment with a qualifying integrated D-SNP. Gaining/losing/changing LIS/Medicaid and notification have separate three-month routes; an application or income report is not approved status.',
  'actual LIS/full-dual eligibility and dates|at-risk status|aligned Medicaid plan|integrated SNP status|change/notice date',
  [C423+'423.38','cfr-423-153-20261027:CFR:423.153','cfr-422-2-20261027:CFR:422.2',G+'30.6.7',G+'30.6.8',G+'30.6.35','cfr-423-P-reused:CFR:423.772']),
R('CD10','C/D disasters, CMS permission and event-dependent rights',
  'C/D disaster SEP generally continues through two full calendar months after the applicable event/declaration end, requires a missed valid election opportunity caused by the event and designated residence/decision-maker conditions. Sanction, contract-violation, network-change and catch-all routes can require CMS approval or notice. Five-star eligibility also needs an actually available qualifying plan, not a generic national right.',
  'declaration/end/extensions and area|missed window|CMS approval/notice|actual plan status/rating and service area',
  [C422+'422.62',C423+'423.38',G+'30.6.22',G+'30.6.25',G+'30.6.28',G+'30.6.29',G+'30.6.33',G+'30.6.36']),
R('CD11','Receipt, effective date, overlapping windows and cancellation',
  'Application receipt, completion, entitlement and coverage-effective dates differ. Ordinary C/D SEP and OEP coverage is next month unless a specific route permits something else. If more than one valid period gives different dates, seek the beneficiary’s choice; use regulatory priority only if choice cannot be obtained. Cancellation/reinstatement/retroactive transactions require their actual processing rules and agency/plan action, not a synthetic assumption.',
  'receipt/completion|valid period(s)|beneficiary choice and contact record|plan/CMS transaction outcome|existing coverage end',
  [C422+'422.68',C423+'423.40',G+'30.7',G+'30.8',G+'50.3',G+'50.5',G+'70.1',G+'70.2',G+'70.3',G+'70.4',G+'70.5']),
R('CD12','Contract ending and non-renewal periods',
  'Nonrenewal, sponsor/mutual-consent termination and CMS termination have different windows and date choices; consolidation is not automatically termination. Preserve the 2026 guide’s exact branches and examples, but hold automated dates for mutual-consent termination: its window wording/example are inconsistent and the 2027 memo expressly announces a correction. A 2027 correction is not silently made a 2026 rule.',
  'exact legal termination type|effective date and notice|CMS instructions|receipt and beneficiary choice',
  [C422+'422.62',C423+'423.38',G+'30.6.10',H('cms-2027-transition-memo')]),
R('PA01','Premium Part A late enrollment',
  'After exclusions, each full 12 countable months determines the surcharge period. In 2026 the increase is capped at 10 percent and lasts twice the number of full 12-month periods (24 surcharge months per full period). Premium-free A has no premium-A LEP. Reenrollment, SEP, working-disabled and relief conditions stay separate; no dollar premium is independently recreated from L01.',
  'premium-A eligibility|complete countable/excluded month history|previous surcharge and relief|annual applicable premium',
  [C406+'406.32',C406+'406.33',C406+'406.34',H('cms-ab-enrollment')]),
R('PB01','Part B late enrollment',
  'Increase is 10 percent of the applicable standard premium per full 12 countable months. For enrollment in 2026 count through the enrollment month, not automatically March or the GEP end. Exclude qualifying current-work, buy-in, pre-age-65 and exceptional-SEP periods as directed; generally paid while B is held, with resets/relief and reenrollment exceptions. IRMAA is not the surcharge basis.',
  'B IEP and enrollment date|complete coverage/SEP/buy-in history|age-65 reset|annual standard premium|agency determination',
  [C408+'408.22',C408+'408.24',C408+'408.25',H('ssa-0601001010')]),
R('PD01','Part D 63-day trigger and creditable coverage',
  'The trigger is a continuous gap of at least 63 days after D IEP while D-eligible, without D or other creditable drug coverage. Separate gaps do not become one continuous gap by addition. Creditable refers to the annual drug benefit standard, not merely having health insurance; annual notices and actual dates matter. Unknown creditability remains unknown, not zero penalty or a definite penalty.',
  'D IEP and eligibility|D effective/end dates|dated creditable-coverage notices|coverage gaps|LIS/subsequent IEP history',
  [C423+'423.46',C423+'423.56',L+'20.1',L+'20.2',L+'30.1',L+'30.2']),
R('PD02','2026 Part D penalty basis and rounding',
  'CMS publishes a 2026 national base beneficiary premium of $38.99. The operational LEP is 1 percent of the annual national base for each full uncovered calendar month, rounded to the nearest $0.10. Do not use the selected plan premium, divide days by 30, count partial months as full or reuse the 2026 base for 2027. The regulation retains CMS actuarial authority; the operational method comes from the CMS LEP chapter.',
  'CMS countable uncovered months|actual coverage year|LIS/reset findings|official LEP notice',
  [H('cms-d-base-2026'),'cfr-423-286-20261027:CFR:423.286',L+'20.4',L+'30.2']),
R('PD03','Part D duration, LIS and later IEP resets',
  'LEP ordinarily continues during later D coverage and can return after a break. Qualifying LIS status or a subsequent IEP resets uncovered-month history under the detailed rules; a prior penalty does not automatically return merely because LIS later ends. Later new countable gaps can create a new LEP. DMP, territories, PACE and disenrollment-specific processing exceptions are retained in the source inventory.',
  'CMS NUNCMO/LEP history|verified LIS dates|subsequent IEP|later coverage gaps|error corrections',
  [L+'20.6',L+'30.1.3',L+'30.1.4',L+'30.3',L+'50.4',L+'50.4.1',L+'50.4.2','cfr-423-P-reused:CFR:423.780']),
R('PD04','Part D correction and reconsideration',
  'Keep employer/plan creditability evidence and the plan/CMS uncovered-month history. The notice allows reconsideration within 60 calendar days of its date; good-cause late requests require an individual decision. Pending review does not itself remove payment responsibility. Sponsor error, corrected coverage dates, IRE decisions and invalid LIS resets have specific correction processes. No deadline is calculated from an assumed receipt date.',
  'actual notice date|creditable history and attestation|plan/CMS records|good-cause finding if late|decision and revised bill',
  [C423+'423.46',C423+'423.56',L+'50.2',L+'50.2.1',L+'50.2.2',L+'50.2.3',L+'70.1']),
R('CO01','Working aged and disabled payer order',
  'For working-aged GHP, the 20-employee rule governs when the plan rather than Medicare is primary; disability LGHP uses 100 employees, with multi-employer and current-employment definitions. These are payer rules, not permission to skip enrollment solely from a headcount. Actual plan/employment, age/disability basis and multi-employer exceptions require verification.',
  'employer size and measurement period|multi-employer evidence|current employment|basis of entitlement|GHP policy and CMS coordination',
  [C411+'411.101',C411+'411.104',C411+'411.170',C411+'411.172',C411+'411.200',C411+'411.204',C411+'411.206',H('ssa-0600805266')]),
R('CO02','ESRD coordination',
  'ESRD has a 30-month coordination period and dual-entitlement/prior-primary-payer exceptions. Coverage eligibility, dialysis/transplant timing and payer order are separate questions; do not apply ordinary working-aged SEP assumptions just from an ESRD label.',
  'ESRD eligibility/entitlement start|prior age/disability Medicare and payer order|GHP status|dialysis/transplant records',
  [C411+'411.160',C411+'411.162',C411+'411.163',C406+'406.13',H('cms-esrd-coordination'),H('cms-msp-overview'),H('cms-msp-ch2')]),
R('CO03','COBRA, retiree coverage, VA and TRICARE',
  'COBRA/retiree coverage generally does not extend the ordinary B employment SEP, while drug coverage may separately be creditable for D. VA drug coverage does not create a B SEP; VA and Medicare systems have distinct service/billing rules. TFL ordinarily requires A and B; active-duty/dependant exceptions require the exact TRICARE route. Preserve employer/family no-loss warnings and confirm actual policy.',
  'current vs former work status|benefit handbook|drug creditability|VA/TRICARE status|Medicare dates|administrator confirmation',
  [H('ssa-0600805266'),H('medicare-retiree-coordination'),H('va-medicare-coordination'),H('tricare-medicare-eligibility'),G+'50.7']),
R('CO04','Federal employee and postal coverage',
  'OPM distinguishes active work, retirement, FEHB and PSHB. FEHB has no B enrollment requirement; PSHB has a B requirement with dated retirement/age, foreign-residence, qualifying VA/IHS and related family exceptions. For qualifying historical 2024 PSRA SEP enrollees, USPS pays the B LEP while PSHB remains active or validly suspended; cancellation can transfer payment responsibility to the person, with a family-coverage exception. This is payment by USPS, not forgiveness of the penalty. Postal drug integration/opt-out and no-loss conditions are separate. Benefit-specific preservation and deadline questions need actual OPM/plan documents.',
  'FEHB vs PSHB identity|employment/retirement and Medicare dates|applicable exceptions|family and drug coverage|OPM/plan notice',
  [H('opm-payer'),H('opm-medicare'),H('opm-active'),H('opm-annuitant'),H('opm-pshb-annuitant'),H('opm-pshb-exceptions')]),
]
