GUIDE_MAP={1:['MA:c','D:c:5'],2:['MA:b:10','D:a'],3:['D:c:16'],4:['MA:b:8','D:c:24'],5:['D:c:15'],6:['D:c:25'],7:['D:c:4'],8:['D:c:9'],9:['MA:b:12','D:c:17'],10:['MA:b:1','D:c:6'],11:['MA:b:6','D:c:13'],12:['MA:b:7','D:c:14'],13:['MA:b:11','D:c:27'],14:['MA:b:13','D:c:28'],15:['D:c:19'],16:['MA:b:4','D:c:11'],17:['MA:b:19','D:c:1'],18:['MA:b:20','D:c:2'],19:['MA:b:14','D:c:18'],20:['MA:b:2','D:c:7'],21:['MA:b:21','D:c:3'],22:['MA:b:15','D:c:20'],23:['D:c:29'],24:['MA:b:17','D:c:22'],25:['MA:b:18','D:c:23'],26:['MA:b:24','D:c:31'],27:['MA:b:25','D:c:32'],28:['MA:b:3','D:c:8'],29:['MA:b:5','D:c:12'],30:['D:c:10'],31:['D:c:33'],32:['MA:b:16','D:c:21'],33:['MA:b:23','D:c:30'],34:['MA:b:26','D:c:34'],35:['D:c:35'],36:['MA:b:27','D:c:36']}
RECONCILIATIONS=[
('RC01','Early IEP coverage','AB03','resolved_published_rule','CMS overview says next month for all IEP enrollment. 407.25(a)(2) and SSA .165 preserve first-eligibility-month coverage for early enrollment; use that branch.',[H('cms-ab-enrollment'),C407+'407.25',H('ssa-0600805165')]),
('RC02','GHP coverage cross-reference','AB08','resolved_published_rule','407.20(e)/407.25(c) cite 406.24(d), now the additional-SEP paragraph. Effective-date heading 406.24(e) and SSA .276 agree; retain literal cross-reference but use (e).',[C406+'406.24',C407+'407.20',C407+'407.25',H('ssa-0600805276')]),
('RC03','ICEP delayed-B examples','CD04','resolved_published_rule_review_disposition_pending','January and October 422.62(a)(1) agree with guide main rule: later of second month after A+B or B IEP end. Guide note and Smith/Jones example ends are stale. Use operative formula, not those examples. No 2027 rule is backdated.',['ecfr-422-62-jan:CFR:422.62',C422+'422.62',G+'30.2']),
('RC04','International-volunteer window','AB09','resolved_published_rule','CMS overview says month following; 406.25(b), 407.21(b), SSA .350 and its worked examples say month including cessation. Program duration, not individual service duration, is the 12-month test; rollback is conditional.',[H('cms-ab-enrollment'),C406+'406.25',C407+'407.21',H('ssa-0600805350')]),
('RC05','Historical LGHP sunset footnote','AB07','operational_rule_supported_stale_footnote_retained','407.20/408.24 retain historical October-1998 wording. Current SSA policy explicitly provides qualifying disabled family-member LGHP SEPs. Do not deny the 2026 route based only on that footnote; qualified review of legal presentation remains.',[C407+'407.20',C408+'408.24',H('ssa-0600805266')]),
('RC06','Mutual-consent contract termination window','CD12','exact_personal_date_held','2026 guide wording and example do not align on the start anchored to the termination date/month; 2027 memo announces a correction. Preserve 2026 text; require CMS/qualified confirmation for that exceptional exact deadline.',[G+'30.6.10',H('cms-2027-transition-memo')]),
('RC07','Monthly LIS versus historical quarterly and unrestricted MA','CD09','resolved_published_rule','Use current PDP monthly rule and at-risk exception, separate integrated-D-SNP aligned-enrollment route. No generic monthly MA right or assumed Medicaid eligibility.',[C423+'423.38',G+'30.6.7',G+'30.6.35']),
('RC08','Different enrollment and coverage years','CD05','resolved_published_rule','Keep AEP-2025-for-2026 and AEP-2026-for-2027 as two rows. Future 2027 memo is explicitly effective January 1, 2027 and not a 2026 catalog or LEP basis.',[G+'30.3',H('cms-2027-transition-memo')]),
('RC09','First-day birthday relief','AB02','resolved_conditional_exception','Prior-month age attainment shifts ordinary IEP. SSA .153 allows a deemed IEP for filing in the first month after actual IEP, unless file shows knowledge of prior-month rule. No universal automatic extra month.',[H('ssa-0600805153'),H('ssa-0600805015')]),
('RC10','LEP national basis, months and reset','PD02','resolved_published_rule','2026 operational base is 38.99, full calendar months after a qualifying continuous gap, not plan premium or days/30. Verified LIS/subsequent IEP reset is separate from merely applying for assistance.',[H('cms-d-base-2026'),L+'20.4',L+'30.2',L+'50.4']),
('RC11','ESRD coordination obsolete CFR duration','CO02','current_CMS_rule_supported_stale_regulation_retained','411.162 retains old 12/18-month coordination text and old examples. Current CMS ESRD guidance and MSP manual state the 30-month coordination period, with dual-entitlement and eligibility-start conditions. Use current CMS operational rule; preserve the old regulation and require qualified review of legal presentation.',[C411+'411.162',H('cms-esrd-coordination'),H('cms-msp-overview'),H('cms-msp-ch2')]),
]
